from pathlib import Path
import base64
import subprocess

BASE = "2642426"

def proc(args, check=True):
    return subprocess.run(
        args,
        check=check,
        capture_output=True,
        text=True,
        encoding="utf-8",
    )

head = proc(["git", "rev-parse", "--short", "HEAD"]).stdout.strip()
if not head.startswith(BASE):
    raise SystemExit(
        f"This patch is built for {BASE}, but HEAD is {head}. "
        "No files were changed."
    )

# Untracked helper scripts are fine. Tracked code must be clean.
if proc(["git", "diff", "--quiet"], check=False).returncode != 0:
    raise SystemExit(
        "Tracked files contain unstaged changes. No files were changed."
    )
if proc(["git", "diff", "--cached", "--quiet"], check=False).returncode != 0:
    raise SystemExit(
        "Tracked files contain staged changes. No files were changed."
    )

layout_path = Path("app/(portal)/layout.tsx")
style_path = Path("components/sepulchria/sep-ui-unified.css")

if not layout_path.exists():
    raise SystemExit("Missing app/(portal)/layout.tsx. No files were changed.")

layout = layout_path.read_text(encoding="utf-8")
anchor = 'import { Suspense, type ReactNode } from "react";'
style_import = 'import "@/components/sepulchria/sep-ui-unified.css";'

if anchor not in layout:
    raise SystemExit(
        "Expected Portal layout import anchor not found. No files were changed."
    )

style_path.parent.mkdir(parents=True, exist_ok=True)
style_path.write_text(
    base64.b64decode("").decode("utf-8"),
    encoding="utf-8",
)

if style_import not in layout:
    layout = layout.replace(
        anchor,
        anchor + "\n\n" + style_import,
        1,
    )
    layout_path.write_text(layout, encoding="utf-8")

print("SUCCESS")
print("")
print("Sepulchria UI unification applied from the supplied canonical examples.")
print("")
print("Changed exactly two repository files:")
print("  app/(portal)/layout.tsx")
print("  components/sepulchria/sep-ui-unified.css")
print("")
print("Canonicalised:")
print("  - ordinary text buttons / bordered action links")
print("  - icon-button border/background language")
print("  - existing panel/card/frame borders")
print("  - inputs, selects and textareas")
print("  - right/context sidebar rows and framed controls")
print("  - existing modal frames and modal controls")
print("")
print("Explicitly NOT changed:")
print("  - left sidebar")
print("  - layouts / dimensions / routing")
print("  - semantic red/amber/green actions")
print("  - gameplay / server actions / data")
print("  - 3D / embossing (that comes later)")
print("")
print("Run: npm run build")
